using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evaluations;

public class EvaluationFixture : IAsyncLifetime
{
    private DistributedApplicationTestingBuilder? _appBuilder;
    private DistributedApplication? _app;

    public IChatClient ChatClient { get; private set; } = null!;

    public async ValueTask InitializeAsync()
    {
        _appBuilder = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        _app = await _appBuilder.BuildAsync();
        await _app.StartAsync();

        var chatClientName = "chat";
        ChatClient = _app.Services
            .GetRequiredKeyedService<IChatClient>(chatClientName);
    }

    public async ValueTask DisposeAsync()
    {
        if (_app is not null)
        {
            await _app.StopAsync();
            await _app.DisposeAsync();
        }
    }

    public static ChatConfiguration CreateChatConfiguration(IChatClient chatClient)
    {
        return new ChatConfiguration(chatClient);
    }

    public static IEnumerable<IEvaluator> CreateEvaluators()
    {
        yield return new CoherenceEvaluator();
        yield return new RelevanceEvaluator();
        yield return new FluencyEvaluator();
        yield return new GroundednessEvaluator();
    }
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;

namespace MyApp.Evaluations;

public class EvaluationTests : IClassFixture<EvaluationFixture>
{
    private readonly EvaluationFixture _fixture;

    public EvaluationTests(EvaluationFixture fixture)
    {
        _fixture = fixture;
    }

    [Fact]
    public async Task Chat_Response_MeetsQualityThresholds()
    {
        // Arrange
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        // Act
        var response = await _fixture.ChatClient.GetResponseAsync(messages);

        // Assert - basic response validation
        Assert.NotNull(response);
        Assert.NotEmpty(response.Text);

        // Evaluate quality using AI evaluators
        var chatConfiguration = EvaluationFixture.CreateChatConfiguration(_fixture.ChatClient);
        var evaluators = EvaluationFixture.CreateEvaluators().ToList();

        messages.Add(response.ToChatMessage());

        var context = new EvaluatorContext(chatConfiguration)
        {
            TurnContext = new TurnContext
            {
                Messages = messages,
                GroundTruth = "The capital of France is Paris."
            }
        };

        foreach (var evaluator in evaluators)
        {
            var result = await evaluator.EvaluateAsync(context);
            // Verify evaluators ran without errors
            Assert.NotNull(result);
        }
    }

    [Fact]
    public async Task Chat_Response_IsCoherent()
    {
        // Arrange
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Explain photosynthesis in one sentence.")
        };

        // Act
        var response = await _fixture.ChatClient.GetResponseAsync(messages);

        // Assert
        Assert.NotNull(response);
        Assert.NotEmpty(response.Text);
    }
}

